summary=[]
for name in ['probe-exposure','target-leaf']:
 R=A/name;assert not(R/'FROZEN').exists()
 status=R/'final-evidence/status.json'
 previous=status.read_bytes();(R/'final-evidence/status-before-final-review.json').write_bytes(previous)
 obj=json.loads(previous);obj['measured_time']=stamp;obj['status']='CLEAR; complete own public blocks read; final evidence checked'
 obj['aggregate_build']='PASS4195 jobs; checked axiom dependencies of 79883 MicroCFTA theorems'
 status.write_text(json.dumps(obj,indent=2)+'\n')
 (R/'report.txt').write_text(texts[name])
 index=json.loads((R/'source-index.json').read_text());checks=0
 for record in index['sources']:
  data=Path(record['snapshot']).read_bytes()
  assert len(data)==record['bytes'] and H(data)==record['sha256'],record['snapshot']
  source=Path(record['source']);assert source.read_bytes()==data,('original differs',source)
  checks+=1
  for cut in record['cuts']:
   part=b''.join(data.splitlines(keepends=True)[cut['first_line']-1:cut['last_line']])
   copied=Path(cut['snapshot']).read_bytes();assert part==copied,cut
   assert len(copied)==cut['bytes'] and H(copied)==cut['sha256'],cut
   checks+=1
 for src in obj['final_source_identities']:
  original=Path(src['source']);assert len(original.read_bytes())==src['bytes'] and H(original.read_bytes())==src['sha256']
 dataValidation={'measured_time':stamp,'status':'PASS','source_records':len(index['sources']),
  'literal_cuts':sum(len(x['cuts']) for x in index['sources']),'source_and_cut_byte_checks':checks,
  'installed_final_sources_match_retained':True,'all_twelve_old_blocks_literal_equal':True,
  'manifest_exclusion':'ONLY own root pins.json and FROZEN; all nested files remain included'}
 (R/'final-byte-validation.json').write_text(json.dumps(dataValidation,indent=2)+'\n')
 payloads={}
 for p in sorted(R.rglob('*')):
  if not p.is_file():continue
  rel=str(p.relative_to(R))
  if rel in {'pins.json','FROZEN'}:continue
  data=p.read_bytes();payloads[rel]={'bytes':len(data),'sha256':H(data)}
 pins={'schema':'exact whole payload files; excludes ONLY own root pins.json and FROZEN','files':payloads}
 (R/'pins.json').write_text(json.dumps(pins,indent=2)+'\n')
 seal={'status':'CLEAR / FROZEN','frozen_at':now.isoformat(),'payload_count':len(payloads),'exact_file_count':len(payloads)+2,
  'pins_bytes':len((R/'pins.json').read_bytes()),'pins_sha256':H((R/'pins.json').read_bytes()),
  'report_sha256':H((R/'report.txt').read_bytes()),'source_index_sha256':H((R/'source-index.json').read_bytes()),
  'source_records':len(index['sources']),'literal_cuts':dataValidation['literal_cuts'],'byte_checks':checks,
  'scope': 'Actual raw cold exposure all outcome states and completed Read/Head receipts' if name=='probe-exposure' else 'Actual completed selection/merge/target/leaf whole-heap arity preservation; own full public signatures/defs'}
 (R/'FROZEN').write_text(json.dumps(seal,indent=2)+'\n')
 physical={str(p.relative_to(R)) for p in R.rglob('*') if p.is_file()}
 assert physical==set(payloads)|{'pins.json','FROZEN'},physical-set(payloads)
 for rel,rec in payloads.items():
  data=(R/rel).read_bytes();assert len(data)==rec['bytes'] and H(data)==rec['sha256']
 summary.append({'bundle':name,'manifest':str(R/'pins.json'),'manifest_sha256':seal['pins_sha256'],'FROZEN_sha256':H((R/'FROZEN').read_bytes()),**{k:seal[k] for k in ['payload_count','exact_file_count','source_records','literal_cuts','byte_checks']}})
print(json.dumps(summary,indent=2))
